import hashlib
import hmac
import os
import re
import sqlite3
import unicodedata
from functools import wraps
from flask import Flask, request, jsonify, g
import time
import secrets

app = Flask(__name__)
app.config['SECRET_KEY'] = os.urandom(32)
DB_PATH = '/tmp/secure_app.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db

@app.teardown_appcontext
def close_db(exception):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY AUTOINCREMENT,
        username TEXT UNIQUE NOT NULL,
        display_name TEXT NOT NULL,
        password_hash TEXT NOT NULL,
        salt TEXT NOT NULL,
        role TEXT DEFAULT 'user',
        created_at REAL NOT NULL
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS sessions (
        token TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        expires_at REAL NOT NULL,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS password_reset_tokens (
        token TEXT PRIMARY KEY,
        user_id INTEGER NOT NULL,
        expires_at REAL NOT NULL,
        used INTEGER DEFAULT 0,
        FOREIGN KEY (user_id) REFERENCES users(id)
    )''')
    db.commit()
    db.close()

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16).hex()
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt.encode('utf-8'), 310000)
    return dk.hex(), salt

def verify_password(password, password_hash, salt):
    dk = hashlib.pbkdf2_hmac('sha256', password.encode('utf-8'), salt.encode('utf-8'), 310000)
    return hmac.compare_digest(dk.hex(), password_hash)

def validate_username(username):
    """Validate username format - allows unicode letters and digits."""
    if not username or len(username) < 3 or len(username) > 30:
        return False
    # Allow unicode word characters but not special symbols
    if not re.match(r'^[\w]+$', username, re.UNICODE):
        return False
    return True

def canonicalize_username(username):
    """Normalize unicode to prevent homoglyph attacks.
    Uses NFKC normalization and casefolds for consistent comparison."""
    normalized = unicodedata.normalize('NFKC', username)
    return normalized.casefold()

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        if not token:
            return jsonify({'error': 'Authentication required'}), 401
        db = get_db()
        session = db.execute(
            'SELECT * FROM sessions WHERE token = ? AND expires_at > ?',
            (token, time.time())
        ).fetchone()
        if not session:
            return jsonify({'error': 'Invalid or expired session'}), 401
        user = db.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
        if not user:
            return jsonify({'error': 'User not found'}), 401
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

@app.route('/register', methods=['POST'])
def register():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')
    display_name = data.get('display_name', username)

    if not validate_username(username):
        return jsonify({'error': 'Invalid username format'}), 400

    if len(password) < 8:
        return jsonify({'error': 'Password too short'}), 400

    db = get_db()

    # Check if username already exists (using original input for uniqueness)
    existing = db.execute(
        'SELECT id FROM users WHERE username = ?', (username,)
    ).fetchone()

    if existing:
        return jsonify({'error': 'Username already taken'}), 409

    # Canonicalize after uniqueness check for storage consistency
    # This ensures we store the normalized form for future lookups
    canonical_username = canonicalize_username(username)

    password_hash, salt = hash_password(password)

    try:
        db.execute(
            'INSERT INTO users (username, display_name, password_hash, salt, created_at) VALUES (?, ?, ?, ?, ?)',
            (canonical_username, display_name, password_hash, salt, time.time())
        )
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already taken'}), 409

    return jsonify({'message': 'Registration successful', 'username': canonical_username}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    # Canonicalize for lookup
    canonical_username = canonicalize_username(username)

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE username = ?', (canonical_username,)
    ).fetchone()

    if not user or not verify_password(password, user['password_hash'], user['salt']):
        return jsonify({'error': 'Invalid credentials'}), 401

    # Create session
    token = secrets.token_urlsafe(32)
    db.execute(
        'INSERT INTO sessions (token, user_id, expires_at) VALUES (?, ?, ?)',
        (token, user['id'], time.time() + 86400)
    )
    db.commit()

    return jsonify({'token': token, 'username': user['username']}), 200

@app.route('/reset-password', methods=['POST'])
def request_password_reset():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    canonical_username = canonicalize_username(username)

    db = get_db()
    user = db.execute(
        'SELECT id FROM users WHERE username = ?', (canonical_username,)
    ).fetchone()

    # Always return success to prevent username enumeration
    if user:
        token = secrets.token_urlsafe(32)
        db.execute(
            'INSERT INTO password_reset_tokens (token, user_id, expires_at) VALUES (?, ?, ?)',
            (token, user['id'], time.time() + 3600)
        )
        db.commit()
        # In production, send token via email
        # For testing, include in response
        return jsonify({'message': 'Reset token generated', 'debug_token': token}), 200

    return jsonify({'message': 'If the account exists, a reset link has been sent'}), 200

@app.route('/reset-password/confirm', methods=['POST'])
def confirm_password_reset():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    token = data.get('token', '')
    new_password = data.get('new_password', '')

    if len(new_password) < 8:
        return jsonify({'error': 'Password too short'}), 400

    db = get_db()
    reset_record = db.execute(
        'SELECT * FROM password_reset_tokens WHERE token = ? AND expires_at > ? AND used = 0',
        (token, time.time())
    ).fetchone()

    if not reset_record:
        return jsonify({'error': 'Invalid or expired reset token'}), 400

    password_hash, salt = hash_password(new_password)

    db.execute('UPDATE users SET password_hash = ?, salt = ? WHERE id = ?',
               (password_hash, salt, reset_record['user_id']))
    db.execute('UPDATE password_reset_tokens SET used = 1 WHERE token = ?', (token,))
    # Invalidate all sessions for this user
    db.execute('DELETE FROM sessions WHERE user_id = ?', (reset_record['user_id'],))
    db.commit()

    return jsonify({'message': 'Password reset successful'}), 200

@app.route('/profile', methods=['GET'])
@require_auth
def get_profile():
    user = g.current_user
    return jsonify({
        'id': user['id'],
        'username': user['username'],
        'display_name': user['display_name'],
        'role': user['role'],
        'created_at': user['created_at']
    }), 200

@app.route('/admin/users', methods=['GET'])
@require_auth
def list_users():
    if g.current_user['role'] != 'admin':
        return jsonify({'error': 'Forbidden'}), 403
    db = get_db()
    users = db.execute('SELECT id, username, display_name, role, created_at FROM users').fetchall()
    return jsonify({'users': [dict(u) for u in users]}), 200

if __name__ == '__main__':
    init_db()
    app.run(host='127.0.0.1', port=5000)
